css:
/* Fuente global */
* {
    font-family: Arial, sans-serif;
    font-size: 12px;
}

/* Contenedor principal */
.print-format-container {
    margin: 10px;
}

/* ---------- HEADER ---------- */
#information-table td {
    vertical-align: middle;
    border: none !important;
    padding: 0 !important;
}

/* Logo flexible */
.logo img {
    max-height: 90px;           /* tamaño máximo para portrait */
    width: auto;
    height: auto;
    max-width: 100%;            /* evita desbordes */
}

/* Título */
h3, h4, h5 {
    margin: 4px 0;
}

/* ---------- TABLAS COMPACTAS ---------- */
table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    border: 1px solid black;
    padding: 2px 4px;
    font-size: 11px;
    line-height: 1.1;
}

/* tabla de datos generales */
#table-info td {
    border: none !important;
}

/* que la tabla principal NO se rompa */
table.main-table {
    page-break-inside: avoid;
}

/* Evitar cortes feos */
tr {
    page-break-inside: avoid !important;
}

tbody {
    page-break-inside: auto !important;
}

/* Sección compacta arriba */
.datos-generales {
    margin-top: 8px;
    margin-bottom: 8px;
    border-top: 1px solid black;
    border-bottom: 1px solid black;
    padding: 6px 0;
}

/* Información complementaria */
.info-complement td {
    border: none !important;
    padding: 2px 0 !important;
}

/* Firma */
.footer {
    margin-top: 50px;
    text-align: left;
}

.signature {
    text-align: left;
}

/* ------ Ajustes específicos para impresión ------ */
@media print {
    * {
        font-size: 12px;
    }
    .logo img {
        max-height: 70px;   /* reduce en portrait para que no "rompa" el header */
    }
    th, td {
        font-size: 9.5px !important;
        padding: 1px 2px !important;
    }
}
